#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    double t;
    cin >> n >> t;

    vector<vector<double>> glasses(n + 2, vector<double>(n + 2, 0.0));
    glasses[0][0] = t;

    int ans = 0;

    for (int row = 0; row < n; ++row) {
        for (int col = 0; col <= row; ++col) {
            if (glasses[row][col] >= 1.0) {
                ++ans;
                double overflow = (glasses[row][col] - 1.0) / 2.0;
                glasses[row + 1][col] += overflow;
                glasses[row + 1][col + 1] += overflow;
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    double t;
    cin >> n >> t;

    if (n <= 0) {
        cout << 0 << '\n';
        return 0;
    }

    long long total = 1LL * n * (n + 1) / 2;
    vector<double> a(total, 0.0);
    a[0] = t;

    long long i = 0;
    for (int row = 1; row <= n; ++row) {
        for (int col = 1; col <= row; ++col, ++i) {
            double overflow = max(0.0, a[i] - 1.0);
            a[i] = min(1.0, a[i]);

            if (row < n) {
                a[i + row] += overflow / 2.0;
                a[i + row + 1] += overflow / 2.0;
            }
        }
    }

    int ans = 0;
    for (double amount : a) {
        if (amount >= 1.0) {
            ++ans;
        }
    }

    cout << ans << '\n';
    return 0;
}

