int main() {
    int n;
    double t;
    cin >> n >> t;

    vector<vector<double>> a(n + 1);
    for (int row = 0; row <= n; ++row)
        a[row].assign(row + 1, 0.0);

    if (n > 0)
        a[0][0] = t;

    int ans = 0;

    for (int row = 0; row < n; ++row) {
        for (int col = 0; col <= row; ++col) {
            if (a[row][col] >= 1.0)
                ++ans;

            double excess = max(0.0, a[row][col] - 1.0);
            a[row + 1][col] += excess / 2.0;
            a[row + 1][col + 1] += excess / 2.0;
        }
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double t;
    cin >> n >> t;

    if (n <= 0) {
        cout << 0 << '\n';
        return 0;
    }

    const size_t total = static_cast<size_t>(n) * (n + 1) / 2;
    vector<double> a(total, 0.0);
    a[0] = t;

    int ans = 0;

    for (int row = 1; row <= n; ++row) {
        size_t start = static_cast<size_t>(row - 1) * row / 2;

        for (int col = 0; col < row; ++col) {
            size_t i = start + col;
            double overflow = max(0.0, a[i] - 1.0);
            a[i] = min(1.0, a[i]);

            if (a[i] >= 1.0)
                ++ans;

            if (row < n) {
                a[i + row] += overflow / 2.0;
                a[i + row + 1] += overflow / 2.0;
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

